<?php
require __DIR__.'/config.php'; require_role(['admin','teacher']);
$students=read_json('students');$classes=read_json('classes');$attendance=read_json('attendance');$classId=(int)($_GET['class_id']??0);$date=$_GET['date']??date('Y-m-d');
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$classId=(int)$_POST['class_id'];$date=$_POST['date'];$statuses=$_POST['status']??[];$notes=$_POST['note']??[];
foreach($statuses as $sid=>$status){$sid=(int)$sid;$found=false;foreach($attendance as &$a)if((int)$a['student_id']===$sid&&($a['date']??'')===$date){$a['status']=$status;$a['note']=trim($notes[$sid]??'');$found=true;break;}unset($a);if(!$found)$attendance[]=['id'=>next_id($attendance),'student_id'=>$sid,'date'=>$date,'status'=>$status,'note'=>trim($notes[$sid]??'')];}
write_json('attendance',$attendance);log_action('bulk_save','attendance',$classId);flash('Attendance saved.');redirect('attendance-register.php?class_id='.$classId.'&date='.$date);}
$roster=array_values(array_filter($students,fn($s)=>(int)($s['class_id']??0)===$classId));
function attval($a,$sid,$date){foreach($a as $x)if((int)$x['student_id']===$sid&&($x['date']??'')===$date)return $x['status']??'Present';return 'Present';}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Attendance — Ridgefield</title><link rel="stylesheet" href="cms.css"><style>.wrap{max-width:1100px;margin:auto;padding:28px}.table{width:100%;border-collapse:collapse;margin-top:20px}.table th,.table td{padding:9px;border-bottom:1px solid #ddd;text-align:left}@media(max-width:800px){.table{display:block;overflow:auto}}</style><link rel="stylesheet" href="assets/dynamic-site.css">
</head><body class="rf-dynamic"><div class="wrap"><p><a href="school.php">← School Management</a></p><h1>Attendance Register</h1><form method="get"><label>Class<select name="class_id" required><option value="">Select class</option><?php foreach($classes as $c):?><option value="<?=$c['id']?>" <?=$classId===$c['id']?'selected':''?>><?=h($c['name'])?></option><?php endforeach;?></select></label> <label>Date<input type="date" name="date" value="<?=h($date)?>"></label> <button>Load</button></form><?php if($classId):?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="class_id" value="<?=$classId?>"><input type="hidden" name="date" value="<?=h($date)?>"><table class="table"><tr><th>Learner</th><th>Status</th><th>Note</th></tr><?php foreach($roster as $st):$v=attval($attendance,$st['id'],$date);?><tr><td><?=h($st['name'])?></td><td><select name="status[<?=$st['id']?>]"><option <?=$v==='Present'?'selected':''?>>Present</option><option <?=$v==='Late'?'selected':''?>>Late</option><option <?=$v==='Absent'?'selected':''?>>Absent</option><option <?=$v==='Excused'?'selected':''?>>Excused</option></select></td><td><input name="note[<?=$st['id']?>]"></td></tr><?php endforeach;?></table><p><button>Save attendance</button></p></form><?php endif;?></div><script src="assets/dynamic-site.js"></script>
</body></html>